// Parse Evolution API webhook payload.
// Evolution wraps the message in body.data.message. Adapt if your version differs.
const raw = JSON.parse(JSON.stringify($('Webhook: Evolution API').item.json));
const body = raw.body || raw;
const data = (body && body.data) || {};
const key  = data.key || {};
const msg  = data.message || {};

// Phone normalization (drop @s.whatsapp.net suffix)
const remoteJid = String(key.remoteJid || data.remoteJid || '');
const phone = remoteJid.split('@')[0];

// Text from the various Evolution payload shapes (text, extendedText, conversation)
const text = msg.conversation || msg.text || (msg.extendedTextMessage && msg.extendedTextMessage.text) || '';
const push_name = data.pushName || data.push_name || null;
const is_from_me = key.fromMe === true;

if (is_from_me) throw new Error('SKIP_OWN_MESSAGE');
if (!phone) throw new Error('INVALID_PAYLOAD: missing phone');

const session_key = `${$env.BUSINESS_ID}:${phone}`;

return [{ json: {
  message_id: key.id || null,
  phone,
  push_name,
  text: String(text).trim(),
  session_key,
  received_at: new Date().toISOString()
}}];

// Build LLM context: merge session state + busy slots + service catalog.
// Materialize proxies (avoid Task Runner timeout on nested objects).
const parsed = JSON.parse(JSON.stringify($('Parse Evolution Payload').item.json));
const session = JSON.parse(JSON.stringify($('Load/Init Session').item.json));
const gcalRaw = JSON.parse(JSON.stringify($input.item.json));

const busy = (gcalRaw.items || []).map(ev => ({
  start: ev.start && (ev.start.dateTime || ev.start.date),
  end:   ev.end   && (ev.end.dateTime   || ev.end.date),
  summary: ev.summary || null
}));

// Service catalog hardcoded for the demo (in production, SELECT FROM services).
const services = [
  { id: '11111111-aaaa-bbbb-cccc-111111111111', name: 'Classic haircut',     duration_min: 30, price: 25 },
  { id: '22222222-aaaa-bbbb-cccc-222222222222', name: 'Haircut + beard',     duration_min: 45, price: 38 },
  { id: '33333333-aaaa-bbbb-cccc-333333333333', name: 'Hair color',          duration_min: 90, price: 75 },
  { id: '44444444-aaaa-bbbb-cccc-444444444444', name: 'Manicure',            duration_min: 45, price: 30 }
];

const tz = $env.BUSINESS_TIMEZONE || 'America/Argentina/Buenos_Aires';
const lang = ($env.BOT_LANG || 'en').toLowerCase().startsWith('es') ? 'es' : 'en';
const nowInTz = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date());

return [{ json: {
  ...parsed,
  state: session.state || 'IDLE',
  context: session.context || {},
  busy,
  services,
  business_timezone: tz,
  current_time_local: nowInTz,
  lang
}}];

