// Normalize LLM response across providers + whitelist-validate next_action.
const ctx = JSON.parse(JSON.stringify($('Build LLM Context').item.json));
const raw = JSON.parse(JSON.stringify($input.item.json));
const provider = $env.LLM_PROVIDER || 'openai';

const ALLOWED_INTENTS = ['book', 'consult', 'cancel', 'reschedule', 'fallback'];
const ALLOWED_ACTIONS = ['greet', 'ask_service', 'ask_date', 'ask_time', 'show_slots', 'confirm_booking', 'fallback'];

let content = '';
let parsed = null;
let parse_error = null;

try {
  if (provider === 'openai') {
    content = raw.choices && raw.choices[0] && raw.choices[0].message ? raw.choices[0].message.content : '';
  } else if (provider === 'anthropic') {
    content = raw.content && raw.content[0] && raw.content[0].text ? raw.content[0].text : '';
  }
  const m = content.match(/\{[\s\S]*\}/);
  if (m) parsed = JSON.parse(m[0]);
} catch (e) {
  parse_error = e.message;
}

// Whitelist validation: any value outside allowed sets falls back to safe defaults.
const intent = parsed && ALLOWED_INTENTS.includes(parsed.intent) ? parsed.intent : 'fallback';
const next_action = parsed && ALLOWED_ACTIONS.includes(parsed.next_action) ? parsed.next_action : 'fallback';
const extracted = (parsed && typeof parsed.extracted === 'object') ? parsed.extracted : {};
const user_message = (parsed && parsed.user_message) ? String(parsed.user_message) : '';

// Validate start_at if provided: must parse + be in the future.
let start_at_iso = null;
if (extracted.start_at) {
  const t = Date.parse(extracted.start_at);
  if (!isNaN(t) && t > Date.now()) start_at_iso = new Date(t).toISOString();
}

const service = extracted.service_id
  ? ctx.services.find(s => s.id === extracted.service_id)
  : (extracted.service_name ? ctx.services.find(s => s.name.toLowerCase() === String(extracted.service_name).toLowerCase()) : null);

return [{ json: {
  ...ctx,
  llm_provider: provider,
  llm_raw: raw,
  intent,
  next_action,
  extracted: {
    service: service || null,
    start_at: start_at_iso,
    user_confirmed: extracted.user_confirmed === true
  },
  user_message,
  parse_error
}}];

