// Compose response (i18n) and figure out next state.
// Branch input: either 'book' (after Mark Confirmed) or 'extra' (everything else).
// We detect which branch via $('Mark Booking Confirmed') existing & non-empty.
const llm = JSON.parse(JSON.stringify($('Normalize & Validate LLM').item.json));
const lang = llm.lang;

// Did we just complete a booking?
let booking = null;
try {
  const bk = $('Mark Booking Confirmed').item;
  if (bk && bk.json && bk.json.status === 'CONFIRMED') {
    booking = JSON.parse(JSON.stringify(bk.json));
  }
} catch (e) { /* not in book branch */ }

let pending = null;
try {
  const ip = $('Insert Pending Booking').item;
  if (ip && ip.json && (!ip.json.id || ip.json.id === undefined)) pending = 'taken';
} catch (e) { /* not in book branch */ }

const T = {
  en: {
    booked: (svc, when) => `Confirmed! Your ${svc} is booked for ${when}. See you then. Reply CANCEL to cancel.`,
    taken:  () => `Sorry — that slot was just taken by someone else. Pick another time?`,
    fallback_help: () => `Sorry, I didn't catch that. You can ask me to book, check, or cancel an appointment.`
  },
  es: {
    booked: (svc, when) => `Listo! Te reservé ${svc} para ${when}. Te esperamos. Respondé CANCELAR si querés cancelar.`,
    taken:  () => `Uy — ese horario lo acaba de tomar otra persona. Probamos con otro?`,
    fallback_help: () => `No entendí del todo. Podés pedir un turno, consultar uno, o cancelar.`
  }
}[lang];

const tz = llm.business_timezone;
const fmt = (iso) => new Intl.DateTimeFormat(lang === 'es' ? 'es-AR' : 'en-US', { timeZone: tz, weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' }).format(new Date(iso));

let reply_text;
let next_state;
let next_context = llm.context || {};

if (booking) {
  reply_text = T.booked(llm.extracted.service.name, fmt(booking.start_at));
  next_state = 'BOOKED';
  next_context = { booking_id: booking.id, service_id: llm.extracted.service.id, start_at: booking.start_at };
} else if (pending === 'taken') {
  reply_text = T.taken();
  next_state = 'BOOKING_TIME';  // ask for another time
  next_context = { ...next_context, service_id: llm.extracted.service && llm.extracted.service.id };
} else if (llm.user_message) {
  reply_text = llm.user_message;
  // State transition driven by next_action
  const STATE_BY_ACTION = {
    greet: 'IDLE',
    ask_service: 'BOOKING_SERVICE',
    ask_date: 'BOOKING_DATE',
    ask_time: 'BOOKING_TIME',
    show_slots: 'BOOKING_TIME',
    confirm_booking: 'BOOKING_CONFIRM',
    fallback: llm.state
  };
  next_state = STATE_BY_ACTION[llm.next_action] || llm.state;
  if (llm.extracted.service) next_context.service_id = llm.extracted.service.id;
  if (llm.extracted.start_at) next_context.tentative_start_at = llm.extracted.start_at;
} else {
  reply_text = T.fallback_help();
  next_state = 'IDLE';
}

return [{ json: {
  ...llm,
  reply_text,
  next_state,
  next_context,
  booking
}}];
